'use strict';
(()=>{
 const key='gda-visual-references-v1',roles={palette:'Paleta',typography:'Tipografia',composition:'Composição',materials:'Materiais e luz'};
 const clean=items=>(Array.isArray(items)?items:[]).filter(x=>x&&/^ref-\d+$/.test(x.id)&&/^https:\/\/www\.behance\.net\/gallery\//.test(x.url)).slice(0,6).map(x=>({id:x.id,title:String(x.title).slice(0,180),url:x.url,image:/^https:\/\/mir-s3-cdn-cf\.behance\.net\//.test(x.image)?x.image:'',author:String(x.author||'').slice(0,140),palette:(x.palette||[]).filter(c=>/^#[\da-f]{6}$/i.test(c)).slice(0,5),roles:(x.roles||[]).filter(r=>roles[r]),category:String(x.category||'').slice(0,60)}));
 let fallback=[];
 const read=()=>{try{return clean(JSON.parse(localStorage.getItem(key)||'[]'))}catch{return fallback}};
 const write=items=>{fallback=clean(items);try{localStorage.setItem(key,JSON.stringify(fallback));window.dispatchEvent(new Event('referenceschange'));return true}catch{return false}};
 const text=items=>{items=clean(items);return items.length?'REFERÊNCIAS VISUAIS SELECIONADAS:\n'+items.map((x,i)=>`${i+1}. ${x.title} — ${x.author}\nProjeto: ${x.url}\nImagem de referência: ${x.image}\nAproveitar somente: ${x.roles.map(r=>roles[r]).join(', ')}.${x.roles.includes('palette')?' Cores aproximadas da capa: '+x.palette.join(', ')+'.':''}`).join('\n\n')+'\n\nAbra e avalie as referências antes de descrever detalhes. Se não conseguir acessar as imagens, informe a limitação e peça que sejam anexadas no chat. Cores são extraídas da capa, não um manual oficial. Não invente nomes de fontes: confirme arquivos e licenças. Use as referências para direção, sem copiar logotipos, textos, fotografias ou projetos. A identidade da marca e os arquivos originais de pessoas, produtos e imóveis têm prioridade. Resolva conflitos entre referências e marca antes da produção. Referências não comprovam movimento nem autorizam reutilização de ativos. A primeira entrega continua sendo roteiro, storyboard e vídeo de 10 segundos para aprovação.':''};
 window.VisualReferences={key,roles,clean,read,write,text};
})();
